double calculerMoyenne(const double notes[], int taille)
{
    double somme = 0.0;
    for (int i = 0; i < taille; ++i)
    {
        somme += notes[i];
    }
    return somme / taille;
}

int main()
{
    double notes[4] = { 80.0, 70.0, 90.0, 60.0 };
    cout << calculerMoyenne(notes, 4) << '\n';
    return 0;
}

void doublerPortions(int portions[], int taille)
{
    for (int i = 0; i < taille; ++i)
    {
        portions[i] *= 2;
    }
}

int main()
{
    int portions[3] = { 1, 2, 3 };
    doublerPortions(portions, 3);
    cout << portions[0] << ' ' << portions[2] << '\n';
    return 0;
}

