const int NB_COLONNES = 3;

int sommeGrille(const int g[][NB_COLONNES], int nbLignes)
{
    int somme = 0;
    for (int i = 0; i < nbLignes; ++i)
    {
        for (int j = 0; j < NB_COLONNES; ++j)
        {
            somme += g[i][j];
        }
    }
    return somme;
}

int main()
{
    int g[2][NB_COLONNES] = { { 1, 1, 1 }, { 2, 2, 2 } };
    cout << sommeGrille(g, 2) << '\n';
    return 0;
}

