vector<int> creerCompteARebours(int depart)
{
    vector<int> resultat;
    for (int i = depart; i > 0; --i)
    {
        resultat.push_back(i);
    }
    return resultat;
}

int main()
{
    vector<int> compte = creerCompteARebours(3);
    for (int n : compte)
    {
        cout << n << ' ';
    }
